  // ── Dynamic hero helpers ─────────────────────────────────────────────────────
  function getTimeGreeting() {
    const h = new Date().getHours();
    if (h < 5) return {
      greeting: "Here with you",
      emoji: "🌙",
      accent: "#1A3A5C"
    };
    if (h < 12) return {
      greeting: "Good morning",
      emoji: "☀️",
      accent: "#0D2B2E"
    };
    if (h < 17) return {
      greeting: "Good afternoon",
      emoji: "🌤️",
      accent: "#1A2E1A"
    };
    if (h < 21) return {
      greeting: "Good evening",
      emoji: "🌆",
      accent: "#2B1A2E"
    };
    return {
      greeting: "Still here with you",
      emoji: "🌙",
      accent: "#1A1A3A"
    };
  }
  function getLiveDateLabel() {
    return new Date().toLocaleDateString("en-IN", {
      weekday: "long",
      day: "numeric",
      month: "long"
    });
  }
  function useLiveClock() {
    const [label, setLabel] = (0, _react.useState)(getLiveDateLabel);
    (0, _react.useEffect)(() => {
      const t = setInterval(() => setLabel(getLiveDateLabel()), 60_000);
      return () => clearInterval(t);
    }, []);
    return label;
  }

  // ── Daily rotating prompts — one per day, deterministic by day-of-year ──────
  const DAILY_PROMPTS = ["I feel overwhelmed and don't know where to start", "I'm anxious about something at work today", "I had a conflict with someone close to me", "I feel stuck and can't move forward", "I'm struggling with stress and need clarity", "Something unfair happened and I'm angry", "I feel lonely and disconnected lately", "I can't sleep — my mind won't stop", "I'm worried about money and feel hopeless", "I feel like I'm not good enough", "I'm grieving something and don't know how to cope", "My relationship is causing me pain", "I need to make an important decision and I'm scared", "I feel burnt out and have no energy", "I'm struggling with my health and feel helpless", "I feel misunderstood by people around me", "I have a deadline I'm going to miss and I'm panicking", "Someone treated me unfairly and I need help", "I feel numb and don't feel anything lately", "I'm carrying guilt and don't know how to let go", "I feel restless and don't know why", "I'm afraid of the future", "I feel unappreciated despite working hard", "I need to have a difficult conversation", "I feel pressure from family and don't know how to cope", "I'm going through a big change and feel lost", "I feel jealous and ashamed of it", "I can't stop comparing myself to others", "I feel like I'm failing at everything", "Something bad happened and I need to process it", "I feel hopeful but also scared about a new opportunity", "I'm struggling with a habit that I keep falling back into", "Something from my past keeps coming back and I don't know how to handle it", "The exam pressure is crushing me and I don't know how to cope", "I don't know who I am anymore or what I'm living for", "Parenting is harder than I expected and I feel like I'm failing", "My health is worrying me and I feel helpless about it", "I feel ashamed of how I look and it's affecting everything I do", "I've lost someone and the grief comes in waves I can't predict", "My marriage or relationship is silently falling apart", "I feel trapped financially and don't know where to turn"];
  function getDailyPrompt() {
    const now = new Date();
    const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / 86400000);
    return DAILY_PROMPTS[dayOfYear % DAILY_PROMPTS.length];
  }

