    const socialHigh = /(family|relative|friend|friends|coworker|boss|teacher|student|parent|child|group|team)/.test(`${draft.familyContext} ${draft.relativeContext} ${draft.friendsContext} ${draft.coworkerContext}`.toLowerCase());
