      emotional: latestEntry !== null ? `Latest check-in: ${latestEntry.toneLabel} / ${latestEntry.score}.` : privateIntakeReport.emotionalRead,
      practical: entryCount > 0 ? `Routine coverage: ${dailyRoutinePlan.actions.filter(action => action.kind === "save" || action.kind === "guide" || action.kind === "play" || action.kind === "focus" || action.kind === "journal").map(action => action.label).join(" · ")}. Weekly average ${weeklyAverage}, monthly average ${monthlyAverage}.` : privateIntakeReport.practicalRead,
      social: privateIntakeReport.socialRead,
      safety: privateIntakeReport.safetyRead,
      nextStep: entryCount > 0 ? `${selectedIssueGuide.steps[0]} Then return to ${routePreview.title}.` : privateIntakeReport.nextStep,
