  // Approximate Lagna (Ascendant) from birth time using the Moon-chart Rashi as
  // the sole chart anchor. Lagna changes every ~2 hours. This remains a simplified
  // approximation; precise Lagna requires local sidereal time.
  function getLagnaFromBirthDetails(dob, birthTime, birthLat, birthLon) {
    if (!birthTime || !/^\d{2}:\d{2}$/.test(birthTime)) return null;
    const hour = parseInt(birthTime.split(":")[0], 10);
    const minute = parseInt(birthTime.split(":")[1], 10);
    if (isNaN(hour) || isNaN(minute)) return null;
    const birthMoment = parseVedicBirthMoment(dob, birthTime);
    let lagnaId = 0;
    let precise = false;
    if (birthMoment && typeof birthLat === "number" && typeof birthLon === "number" && !isNaN(birthLat) && !isNaN(birthLon)) {
      // Real Ascendant: Local Sidereal Time + true obliquity + birth latitude,
      // the standard spherical-astronomy formula used by professional
      // astrology software. This is only possible once the birth place has
      // been geocoded to real coordinates.
      const ascSidereal = getPreciseAscendantSiderealDegrees(birthMoment, birthLat, birthLon);
      lagnaId = Math.min(11, Math.floor(ascSidereal / 30));
      precise = true;
    } else {
      // Fallback approximation (no coordinates yet): anchor off the Sun's
      // sidereal Rashi at sunrise, advancing ~1 sign every 2 hours after.
      // Astronomically more defensible than a Moon anchor (the old bug), but
      // still not a true Ascendant without real lat/lon.
      const sunSiderealLongitude = birthMoment ? normalizeDegrees(getApproxTropicalSunLongitude(birthMoment) - lahiriAyanamsaDegrees(julianDay(birthMoment))) : null;
      const sunRashiId = sunSiderealLongitude !== null ? Math.min(11, Math.floor(sunSiderealLongitude / 30)) : 0;
      const hoursSinceSunrise = (hour - 6 + 24) % 24 + minute / 60;
      const lagnaOffset = Math.floor(hoursSinceSunrise / 2);
      lagnaId = (sunRashiId + lagnaOffset) % 12;
    }
    const lagna = VEDIC_RASHIS[lagnaId];
    // Birth time context
    const period = hour < 4 ? "Late night (Brahma Muhurta approaching)" : hour < 6 ? "Pre-dawn (Brahma Muhurta — auspicious)" : hour < 9 ? "Early morning (Surya rising)" : hour < 12 ? "Morning (Prana Vayu active)" : hour < 15 ? "Midday (Surya apex)" : hour < 18 ? "Afternoon (winding energy)" : hour < 21 ? "Evening (Sandhya Kaal — twilight)" : "Night (Chandra dominant)";
    return {
      lagnaId,
      lagna,
      birthHour: hour,
      lagnaLabel: period,
      precise
    };
  }

  // Vedic 60-year Samvatsara cycle from birth year
  // The Samvatsara (Sanskrit: संवत्सर) is a Jovian year — Jupiter transits 1 Rashi every ~12 years,
  // completing 5 cycles = 60 years. Each has a unique name and life-theme.
  const SAMVATSARA_NAMES = ["Prabhava", "Vibhava", "Shukla", "Pramoda", "Prajapati", "Angirasa", "Shrimukha", "Bhava", "Yuva", "Dhata", "Ishvara", "Bahudhanya", "Pramadi", "Vikrama", "Vrisha", "Chitrabhanu", "Svabhanu", "Tarana", "Parthiva", "Vyaya", "Sarvajit", "Sarvadharin", "Virodhi", "Vikruti", "Khara", "Nandana", "Vijaya", "Jaya", "Manmatha", "Durmukhi", "Hemalamba", "Vilamba", "Vikari", "Sharvari", "Plava", "Shubhakruti", "Shobhakruti", "Krodhi", "Vishvavasu", "Parabhava", "Plavanga", "Kilaka", "Saumya", "Sadharana", "Virodhikrut", "Paridhavi", "Pramadi", "Ananda", "Rakshasa", "Nala", "Pingala", "Kalayukti", "Siddharthi", "Raudra", "Durmati", "Dundubhi", "Rudhirodgari", "Raktakshi", "Krodhana", "Kshaya"];
  const SAMVATSARA_THEMES = ["New beginnings & radiant energy", "Abundance & prosperity", "Clarity & purity of purpose", "Joy & celebration", "Creation & divine parenthood", "Wisdom & divine speech", "Auspiciousness & leadership", "Emotional depth & inner strength", "Youth & vitality", "Protection & duty", "Divine authority & power", "Agricultural wealth & nourishment", "Unpredictability & change", "Valor & courage", "Bull-like determination & patience", "Radiant light & artistic excellence", "Self-luminous confidence", "Crossing barriers & liberation", "Grounded rulership & earthly wisdom", "Release & letting go", "Universal victory & mastery", "Complete abundance & generosity", "Struggle against resistance", "Radical transformation", "Sharpness & cutting through illusions", "Bliss & celebration of life", "Victory after effort", "Triumph & achievement", "Love & passion", "Speaking difficult truths", "Gold-tinted prosperity & balance", "Deep reflection & delay before gain", "Unstable yet creative energy", "Darkness before light", "Fluid adaptability", "Auspicious transformation", "Radiant new becoming", "Righteous anger & power", "Universal dwelling & expansion", "Fall before rise", "Rapid change & restlessness", "Keystone moment & pivot", "Gentle wisdom & peace", "Balance & shared responsibility", "Opposition bringing growth", "Circling back to complete cycles", "Distraction requiring focus", "Pure joy & divine grace", "Asura energy — power & material dominance", "Steadiness & endurance", "Golden hue & charismatic authority", "Merging of time cycles", "Accomplishment of true purpose", "Fierce intensity & power", "Distorted perception — seek clarity", "Drum-beat of cosmic time", "Blood-tinged ambition — use power carefully", "Red-eyed intensity — manage reactions", "Anger cycle — channel wisely", "Completion & dissolution"];
  function getVedicSamvatsara(birthYear) {
    // Samvatsara epoch: year 1893 CE = Samvatsara index 0 (Prabhava) in the Southern tradition
    // Cycle length: 60 years
    const epochYear = 1893;
    const idx = ((birthYear - epochYear) % 60 + 60) % 60;
    return {
      index: idx,
      name: SAMVATSARA_NAMES[idx] ?? "Unknown",
      theme: SAMVATSARA_THEMES[idx] ?? "Cosmic cycle — consult a Jyotishi"
    };
  }

  // Vedic emotional guidance connecting birth chart to current issue dimension
  function getVedicIssueGuidance(issueId, rashiId) {
    const rashiName = VEDIC_RASHIS[rashiId]?.name ?? "your Rashi";
    const guidanceMap = {
      general: `${rashiName} carries an adaptive cosmic energy today. Trust the reading below as context, then return to the Guide tab for your practical next step.`,
      anger: `${rashiName} energy may intensify emotions today. The planetary reading below can help you understand why tension feels heightened. Use the Reset tab before acting on any strong impulse.`,
      anxiety: `For ${rashiName}, today's cosmic cycle influences your nervous system. The Tithi and Nakshatra below indicate the best timing for rest versus action — let them inform, not overwhelm you.`,
      fear: `${rashiName}'s ruling planet offers grounding energy today. The reading below carries a daily orientation for your sign — use it to find one fact-based anchor amid the fear.`,
      overconfidence: `${rashiName} can amplify both confidence and blind spots. Today's Vara and Tithi below help you see which moves are supported and which need a second check.`,
      stigma: `${rashiName}'s journey includes both shadow and light. Today's reading reminds you that the cosmos holds no judgment — only direction. Let it quiet the inner critic.`,
      burnout: `${rashiName} is in a restoration phase today. The Nakshatra below carries restorative energy — use it as permission to rest without guilt.`,
      loneliness: `${rashiName}'s placement today highlights connection themes. The planetary reading below points to which human touchpoints are supported — one call or message today carries cosmic weight.`,
      grief: `${rashiName} energy today is especially suited to processing and releasing. The Tithi below carries release energy. Grief does not need to be hurried — the cosmos today gives you space.`,
      trauma: `${rashiName}'s Nakshatra lord today influences how safety is experienced in the body. The reading below carries a grounding message — read it before any big decision.`,
      addiction: `${rashiName}'s ruling planet influences willpower and desire today. The Vara below shows which days are stronger for discipline and which need extra support. Plan around this.`,
      health: `${rashiName}'s body area is highlighted today. The planetary reading below includes a specific health note for your sign — pay attention to it as one more data point alongside your doctor's advice.`,
      financial: `${rashiName}'s ruling planet governs resources and material stability. Today's reading below contains specific financial guidance for your sign — use it alongside the practical steps in the Help tab.`,
      relationship: `${rashiName}'s seventh-house dynamics are active today. The Tithi below is a key relationship indicator — check whether today favors communication, patience, or space before a difficult conversation.`,
      parenting: `${rashiName}'s nurturing energy is present today. The reading below carries specific guidance for your role as a caregiver — the fifth house themes are worth noting.`,
      academic: `${rashiName} is governed by a planet associated with learning today. The Nakshatra below carries specific properties for study and concentration — align your focus blocks with this energy.`,
      identity: `${rashiName}'s self-expression energy is highlighted in today's reading. The Lagna and Rashi below together paint who you are at a cosmic level — use this as grounding, not a label.`
    };
    return guidanceMap[issueId] ?? `${rashiName}'s energy today offers perspective on your situation. Read the cosmic snapshot below alongside your practical path.`;
  }

  // ── Astro two-way chat engine ────────────────────────────────────────────────
  // User asks anything → engine classifies question, pulls the user's Moon Rashi
  // + current Mahadasha + Nakshatra lord + today's Panchang, and returns a
  // guidance line + a specific Vedic remedy (mantra, gemstone, day-fast, deity).

  function classifyAstroQuestion(text) {
    const t = text.toLowerCase();
    if (/(job|career|work|boss|promotion|interview|salary|business|office|colleague)/.test(t)) return "career";
    if (/(love|partner|husband|wife|girlfriend|boyfriend|marriage|relationship|breakup|fight)/.test(t)) return "relationship";
    if (/(health|sick|pain|illness|disease|body|sleep|energy|tired|doctor)/.test(t)) return "health";
    if (/(money|finance|debt|loan|invest|save|wealth|rich|poor|income|expense)/.test(t)) return "money";
    if (/(family|parent|mother|father|child|kid|son|daughter|sibling|brother|sister|home)/.test(t)) return "family";
    if (/(god|spiritual|meditat|dharma|purpose|soul|karma|moksha|pray|temple)/.test(t)) return "spiritual";
    if (/(when|time|muhurat|start|begin|launch|marriage date|auspicious)/.test(t)) return "timing";
    if (/(who am i|myself|identity|confidence|self)/.test(t)) return "identity";
    return "general";
  }

