  // Fallback Nakshatra → Rashi mapping. Primary Moon Rashi now comes from
  // sidereal Moon longitude because Krittika, Mrigashira, Punarvasu and other
  // nakshatras span sign boundaries. This map is only a defensive fallback.
  const NAKSHATRA_TO_RASHI_ID = [0, 0, 1, 1, 2, 2, 3, 3, 3, 4, 4, 5, 5, 6, 6, 7, 7, 7, 8, 8, 9, 9, 10, 10, 11, 11, 11];

  // Janma Rashi (Moon sign) from sidereal Moon longitude.
  function getMoonRashiFromDOB(dob, birthTime) {
    const nakshatra = getJanmaNakshatra(dob, birthTime);
    if (!nakshatra) return null;
    const rashiId = Math.min(11, Math.floor(nakshatra.siderealMoonLongitude / 30));
    const rashi = VEDIC_RASHIS[rashiId] ?? VEDIC_RASHIS[NAKSHATRA_TO_RASHI_ID[nakshatra.id] ?? 0];
    if (!rashi) return null;
    return {
      rashiId: rashi.id,
      rashi
    };
  }

  // Today's Moon Nakshatra from current sidereal Moon longitude.
  function getTodayNakshatra() {
    return buildNakshatraFromMoonLongitude(getSiderealMoonLongitude(new Date()));
  }

  // Panchang Tithi from Moon-solar angular separation. The solar value is used
  // only as the standard Panchang reference for lunar day calculation.
  function getTodayTithi() {
    const TITHI_NAMES = ["Pratipad", "Dwitiya", "Tritiya", "Chaturthi", "Panchami", "Shashthi", "Saptami", "Ashtami", "Navami", "Dashami", "Ekadashi", "Dwadashi", "Trayodashi", "Chaturdashi", "Purnima/Amavasya"];
    const TITHI_TYPES = ["Nanda", "Bhadra", "Jaya", "Rikta", "Purna", "Nanda", "Bhadra", "Jaya", "Rikta", "Purna", "Nanda", "Bhadra", "Jaya", "Rikta", "Purna"];
    const today = new Date();
    const elongation = normalizeDegrees(getApproxTropicalMoonLongitude(today) - getApproxTropicalSunLongitude(today));
    const tithiNum = Math.min(29, Math.floor(elongation / 12));
    const paksha = tithiNum < 15 ? "Shukla Paksha (Waxing)" : "Krishna Paksha (Waning)";
    const idx = Math.min(tithiNum % 15, 14);
    return {
      number: tithiNum + 1,
      name: TITHI_NAMES[idx] ?? "Purnima/Amavasya",
      type: TITHI_TYPES[idx] ?? "Purna",
      paksha
    };
  }

  // Next Ekadashi (11th lunar day of either paksha) from today, using the same
  // Moon-Sun elongation formula as getTodayTithi. Ekadashi falls roughly every
  // 14-15 days, so a 20-day forward scan always finds the next one -- reuses
  // the existing tropical-longitude helpers rather than adding a new
  // astronomy dependency.
  function getNextEkadashi() {
    for (let daysAhead = 0; daysAhead <= 20; daysAhead++) {
      const candidate = new Date();
      candidate.setDate(candidate.getDate() + daysAhead);
      candidate.setHours(12, 0, 0, 0); // noon local -- avoids tithi boundary flicker near midnight
      const elongation = normalizeDegrees(getApproxTropicalMoonLongitude(candidate) - getApproxTropicalSunLongitude(candidate));
      const tithiNum = Math.min(29, Math.floor(elongation / 12));
      if (tithiNum === 10 || tithiNum === 25) {
        return {
          date: candidate,
          paksha: tithiNum === 10 ? "Shukla" : "Krishna",
          daysAway: daysAhead
        };
      }
    }
    return null;
  }

  // Generate the daily prediction text for a given rashi
  function getVedicDailyPrediction(rashiId, dashaState = null) {
    const predictions = RASHI_DAILY_PREDICTIONS[rashiId];
    const fallback = ["Cosmic energies are aligning for you. Reflect, rest, and trust the divine flow.", "Keep intentions pure and actions selfless.", "Health: Maintain daily routine.", "Spiritually: Offer gratitude to the divine."];
    const today = new Date();
    const dayIdx = today.getDay(); // 0-6
    const dailyLines = predictions?.[dayIdx] ?? predictions?.[0] ?? fallback;
    if (!dashaState) {
      return dailyLines;
    }
    const rashiName = VEDIC_RASHIS[rashiId]?.name ?? "your Rashi";
    return [`What is happening: ${dashaState.currentMahadasha} Mahadasha with ${dashaState.currentAntardasha} Antardasha is active. ${summarizePlanetQuality(dashaState.currentMahadasha)} meets ${summarizePlanetQuality(dashaState.currentAntardasha)} in this phase.`, `Why it is happening: the Mahadasha sets the large life theme, while the Antardasha shows the current sub-pattern. Your Moon Rashi (${rashiName}) decides where that pressure lands in daily life.`, `How long it lasts: about ${formatPhaseSpan(dashaState.antardashaYearsLeft)} remain in the current Antardasha and about ${formatPhaseSpan(dashaState.mahadashaYearsLeft)} remain in the larger Mahadasha.`, ...dailyLines];
  }

