    function classifyCommunityTopic(text) {
      const normalized = text.toLowerCase();
      if (/(student|exam|school|college|class|assignment|paper|hostel)/.test(normalized)) return "student";
      if (/(parent|family|child|care|caregiver)/.test(normalized)) return "care";
      if (/(teacher|professor|hod|dean|principal|faculty)/.test(normalized)) return "education";
      if (/(work|office|job|professional|shift|duty)/.test(normalized)) return "work";
      if (/(complaint|ragging|harass|threat|abuse|police|112|redress)/.test(normalized)) return "complaint";
      if (/(anxiety|anger|burnout|lonely|loneliness|fear|stigma|shame)/.test(normalized)) return "support";
      return "general";
    }
    function createCommunityMessage(text, role, author, tag) {
      return {
        id: `${Date.now()}-${Math.floor(Math.random() * 100000)}`,
        createdAt: new Date().toISOString(),
        author,
        role,
        tag,
        text: text.trim(),
        topic: classifyCommunityTopic(text)
      };
    }
    function inspectCommunitySafety(text) {
      if (adultContentPattern.test(text)) {
        return {
          reason: "adult",
          message: "Adult or explicit content is blocked here."
        };
      }
      if (offensiveLanguagePattern.test(text) || violentThreatPattern.test(text)) {
        return {
          reason: "harassment",
          message: "Offensive or threatening language is blocked here."
        };
      }
      if (maliciousThreatPattern.test(text)) {
        return {
          reason: "spam",
          message: "Unsafe or malicious content is blocked here."
        };
      }
      return null;
    }
    function inspectAIHelpPrompt(text) {
      const normalized = text.toLowerCase();
      const seriousContext = /(abuse|assault|blackmail|complaint|harass|police|professor|ragging|redress|teacher|workplace)/.test(normalized);
      if (adultContentPattern.test(text) && !seriousContext) {
        return {
          reason: "adult",
          message: "Adult or explicit content is blocked here."
        };
      }
      if (offensiveLanguagePattern.test(text)) {
        return {
          reason: "harassment",
          message: "Offensive language is blocked here."
        };
      }
      if (maliciousThreatPattern.test(text)) {
        return {
          reason: "spam",
          message: "Unsafe or malicious content is blocked here."
        };
      }
      return null;
    }
    function detectAIHelpRoute(text) {
      return detectAIHelpRouteFromText(text);
    }

