      const escalateWhen = route === "urgent" ? `Escalate at once if there is assault, self-harm risk, violence, or you feel unsafe.` : route === "redress" ? `Escalate if the first office ignores you, delays without reason, or the situation gets worse.` : route === "professional" ? primaryDimension.escalation : route === "guide" ? primaryDimension.escalation || issue.urgentNote : `Escalate if this is bigger than one reply, then move to Help or SOS.`;
