    const needsCalm = ["self-image", "anxiety", "anger", "burnout", "sadness", "loneliness", "grief", "trauma", "fear", "financial", "health", "academic", "relationship"];
    if (needsCalm.some(theme => has(theme))) {
      steps.push({
        tabId: "focus",
        label: "Ground yourself first",
        emoji: "🌿",
        reason: "The body needs to settle before the mind can make good decisions. Start here.",
        completed: false,
        skipped: false
      });
    }

    // ── 2. Sound / tones for nervous system regulation ───────────────────────────
    if (has("anxiety") || has("burnout") || has("anger") || has("trauma") || has("grief") || has("fear")) {
      steps.push({
        tabId: "tones",
        label: "Sound therapy",
        emoji: "🎵",
        reason: "Binaural and Solfeggio tones directly shift the nervous system — this is not just relaxation, it is neurological regulation.",
        completed: false,
        skipped: false
      });
    }

    // ── 3. Meditation / body practice ────────────────────────────────────────────
    if (has("self-image") || has("loneliness") || has("sadness") || has("grief") || has("trauma") || has("health") || has("addiction") || has("burnout")) {
      steps.push({
        tabId: "meditation",
        label: "Wellness practice",
        emoji: "🪷",
        reason: "A breath or body-scan practice helps process what words cannot fully reach.",
        completed: false,
        skipped: false
      });
    }

    // ── 4. Professional and locality support when symptoms or risk need a real person
    if (route === "professional" || has("health") || has("trauma") || has("addiction") || has("sadness")) {
      steps.push({
        tabId: "search",
        label: "Find real support",
        emoji: "🧭",
        reason: "Use verified professional, clinic, helpline, or locality search before the issue stays only inside the app.",
        completed: false,
        skipped: false
      });
    }

    // ── 4. Guided personalised path ──────────────────────────────────────────────
    steps.push({
      tabId: "aihelp",
      label: "Get personalised guidance",
      emoji: "🤝",
      reason: "Talk through your specific situation and get tailored next steps — not generic advice.",
      completed: false,
      skipped: false
    });

    // ── 5. Journal — write to process ────────────────────────────────────────────
    steps.push({
      tabId: "journal",
      label: "Write it out",
      emoji: "✍️",
      reason: "Getting it onto paper externalises the weight, creates clarity, and shifts perspective.",
      completed: false,
      skipped: false
    });

    // ── 6. 48D Moon Chart layer — when birth details make it operational ─────────
