        dec = 54.432516 - 0.05827105 * T + 0.000051 * Math.cos(DEG2RAD * (122.433576 + 19139.9407476 * T)) + 0.000141 * Math.cos(DEG2RAD * (43.058401 + 38280.8753272 * T)) + 0.000031 * Math.cos(DEG2RAD * (57.663379 + 57420.7517205 * T)) + 0.000005 * Math.cos(DEG2RAD * (79.476401 + 76560.6495004 * T)) + 1.591274 * Math.cos(DEG2RAD * (166.325722 + 0.5042615 * T));
        w = 176.049863 + 350.891982443297 * d + 0.000145 * Math.sin(DEG2RAD * (129.071773 + 19140.0328244 * T)) + 0.000157 * Math.sin(DEG2RAD * (36.352167 + 38281.0473591 * T)) + 0.000040 * Math.sin(DEG2RAD * (56.668646 + 57420.9295360 * T)) + 0.000001 * Math.sin(DEG2RAD * (67.364003 + 76560.2552215 * T)) + 0.000001 * Math.sin(DEG2RAD * (104.792680 + 95700.4387578 * T)) + 0.584542 * Math.sin(DEG2RAD * (95.391654 + 0.5042615 * T));
